// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(this) && target != address(c));
        vm.assume(value <= address(c).balance);
        vm.deal(address(c), value + 1 ether);
        uint256 balBefore = address(c).balance;
        try c.sendMoney(target, value, data) {
            assertTrue(address(c).balance <= balBefore);
        } catch {
            assertTrue(false);
        }
    }
}
